INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas-p1", "partName": "Background: The Fall of Warangal and the Post-Kakatiya Liberation Movement", "bodyMd": "The fall of Warangal in **1323 A.D.** is a landmark event in Telugu history, ending Kakatiya rule and opening space for a liberation movement against Tughlaq authority.\n\n*   This movement was led by a confederation of erstwhile Kakatiya nobles, chief among them:\n    *   The **Musunuri Nayakas**\n    *   The **Recherla Velamas** of Rachakonda and Devarakonda\n    *   The **Reddys** of Kondavidu\n    *   The **Koppula chiefs**\n*   **Musunuri Kapaya Nayaka** recaptured Warangal in **1336 A.D.**\n*   After this recapture, all the above groups established their own independent kingdoms across present-day Andhra and Telangana.\n*   Because the territory of each of these kingdoms was small and their duration short, the polity/statecraft they practiced could not make a lasting mark of its own impact.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas-p2", "partName": "The Musunuri Nayakas (1325–1335 A.D.)", "bodyMd": "### Sources for Musunuri Nayaka History\n\nThe primary sources for reconstructing Musunuri Nayaka history are:\n\n*   Musunuri **Prolaya Nayaka''s** fourteenth-century **Vilasa Copperplate grant** (undated precisely)\n*   Musunuri **Kapaya Nayaka''s Prolavaram (Guraja) record**, dated **1345 A.D.**\n*   Reddy Queen **Anitalli''s Kaluvacheru grant**, dated **1423 A.D.**, which also refers to Prolaya and Kapaya\n*   Inscriptions of the Recherla Padmanayakas at **Pillalamarri, Ainavolu, and Ganapeshwaram**\n*   The literary work **Velugotivari Vamsavali**, and other contemporary accounts\n\n### Musunuri Prolaya Nayaka (1324/1325–1333 A.D.)\n\nProlaya Nayaka was the grandson of **Pota** and son of **Pocha**. Pocha and his three brothers may have served the last Kakatiya ruler, **Prataparudra**.\n\n*   After Warangal''s fall in 1323 A.D., Prolaya took advantage of the discontent under the tyrannical Tughlaq administration to win popular confidence and become a leader in north coastal Andhra.\n*   He received support from all his relations, especially his cousin **Kapaya Nayaka**.\n*   By the time Prolaya assumed leadership in **1324 A.D.**, all of Andhradesa was under the Delhi empire; **Malik Maqbul** was in charge at Warangal with Muslim garrisons stationed at other forts.\n\n**Rebellion (1325 A.D.):**\n\n*   The death of Sultan Ghiyasuddin Tughlaq, and the new sultan Muhammad bin Tughlaq''s preoccupation with family affairs, gave **Prolaya Nayaka** the opening to become among the first rebel leaders to strike against local administrators, in 1325 A.D.\n*   He chose **Rekapalle** on the banks of the Godavari, amidst thick forests and hilly terrain, as his base — a location that made it hard for the enemy to retaliate.\n*   This let him drive away Tughlaq-appointed administrators and occupy the Telangana region as well.\n\n**Supporters and allies:**\n\n*   Surviving veteran generals/administrators from the earlier regime — **Induluri (Ariyeti) Annamantri** and **Kolani Rudradeva** — supported his rebellion.\n*   Younger nobles/chieftains who revolted simultaneously in different parts of Andhradesa:\n    *   **Prolaya Vema Reddy** of Addanki\n    *   **Prolaya Nayaka** of the Koppula family\n    *   **Anapati Nayaka** of the Manchikonda family\n    *   **Recherla Singama Nayaka**\n    *   **Vengabhupala** of Undi\n*   His brother **Musunuri Porlaya Nayaka**, cousins, and other followers also stood by him.\n\n**Achievements and honours:**\n\n*   Prolaya Nayaka inflicted a series of defeats on Tughlaq representatives and established himself as independent ruler of the Godavari region.\n*   The _Bhimesvara Purana_ (Canto I, verse 49) narrates that he granted **Aredu village** (West Godavari district) to **Annamantri** as an _agrahara_, in appreciation of his services.\n*   Prolayavema Reddy independently ruled Punginadu (Guntur–Nellore tract) with Addanki as capital; in his **1325 A.D. Mallavaram epigraph**, he uses the epithet _''mlechchhabdhi kumbhodbjhava''_ (\"a veritable Agastya to the ocean,\" i.e., the Muslim army).\n*   **Recherla Singama Nayaka** established his authority in the Mahbubnagar area.\n*   In Raichur, Kadapa, and Kurnool regions, the **Aravitis** worked to drive away the outsiders.\n\n**Record of reign:**\n\n*   Prolaya Nayaka''s reign was short (**1324–1333 A.D.**).\n*   The fourteenth-century **Vilasa grant**, issued on the occasion of a lunar eclipse (either 1328 or 1333 A.D.), records the grant of Vilasa village in Konasima as an _agrahara_ to the Brahman scholar **Vennaya**, who in turn distributed agrahara lands to other Brahmans. The grant enumerates the achievements of Prolaya''s short rule.\n\n### Musunuri Kapaya Nayaka (1333–1368 A.D.)\n\nProlaya Nayaka had no children. The next heir, his younger brother **Erapota Nayaka**, died in battle, so his cousin **Kapaya Nayaka** ascended the throne at Rekapalle.\n\n**Accession context — the Kampili episode:**\n\n*   In pursuit of the rebel governor of Sagar, Malik Bahauddin Gurshasp, Sultan Muhammad bin Tughlaq''s forces attacked and destroyed **Kampili** in 1327–28 A.D.\n*   Ferishta''s account: Kapaya approached **Ballala III**, the powerful king of Carnatic, and convinced him of the need to avert extermination of Hindus from the Deccan (though no independent evidence confirms this).\n*   Ballala III raised an army and placed part of it under Kapaya Nayaka''s command.\n\n**Recapture of Warangal (1336 A.D.):**\n\n*   Kapaya Nayaka drove away **Malik Maqbul**, the Bain Wazir of Telangana, and occupied Warangal; Maqbul fled to Delhi. Warangal was thus totally lost to the Sultan.\n*   Muhammad bin Tughlaq, occupied with revolts in the north, could not respond in the south.\n*   Kapaya Nayaka assumed rulership of Andhradesa, taking the titles **Andhra Suratrana** and **Andhradesadhisavara**.\n*   Around the same time, per Barani, a relative of Kapaya who had converted to Islam and been loyal to the Tughlaqs raised the banner of revolt at **Kampili**, and Kampili too was lost to the Tughlaqs. Only Daulatabad and Gujarat remained of the sultan''s southern domain.\n\n**Consolidation of power:** To strengthen his position in Telangana and coastal areas north of the Krishna, Kapaya Nayaka conferred high positions on close associates/relatives and entered matrimonial alliances with some of them.\n\n| Associate | Position / Territory | Notes |\n|---|---|---|\n| Anavota Nayaka (cousin) | Governor of coastal area, headquartered first at Toyyeru, later Rajahmahendravaram (Rajahmundry) | Popularly known as **Toyyeti Anavota Nayaka** |\n| Muppabhupa | Ruled Sabbinadu (north-western region), capital Ramagiri (modern Adilabad district) | Patron of Telugu poet **Madiki Singana** |\n| Manchikonda Kunya Nayaka | Built the fort at Korukonda | Son-in-law of Kapaya Nayaka''s brother; guarded against forest-folk raids and aided the coastal governor |\n| Mummadi Nayaka (Kunya''s son) | Married Kapaya Nayaka''s sister''s daughter | — |\n| Namaya Nayaka (Koppula family) | Placed at Pithapuram | — |\n\n*   **Kunavaram**, at the confluence of the Godavari and the Sabari, is named after Kunya Nayaka, indicating the extent of his principality.\n*   The **Ganapesvaram record** indicates Kapaya Nayaka''s authority over the Recherla Velamas of Amanagallu and Pillalamarri — though there is no clear evidence Prolayavema Reddy of Punginadu was ever his subordinate.\n*   Also in existence at this time: the ancient kingdom of the **eastern Gangas of Kalinga**, flourishing for over a thousand years in the area of modern Visakhapatnam, Vizianagaram, Srikakulam and Ganjam districts.\n\n**Downfall and death:**\n\n*   **Recherla Singama Nayaka** (of the Padmanayakas/Velamas), who had cooperated with the Musunuris earlier, began asserting his own power in Telangana, moving his capital to Rajukonda/Rachakonda — a more secure place.\n*   This bid for power caused Kapaya Nayaka to suffer a revolt that forced him to flee. He later recovered, extending his authority up to Pillalamarri and beyond, as shown by the **Pillalamarri inscription of 1357 A.D.**\n*   While Kapaya Nayaka was engrossed fighting the **Bahmanis** (1359–61 A.D.), Singama Nayaka declared independence, extending his kingdom to the river Krishna and capturing forts in the Krishna–Tungabhadra doab.\n*   **1361 A.D.:** Singama Nayaka''s elder son **Anapota Nayaka**, with his brother, stormed **Jallipalli**, massacred its inmates and allies, and assumed the title **Somakulaparasurama**. He then fortified Rachakonda, making it impregnable.\n*   Kapaya Nayaka''s subsequent efforts to assert authority over Anapota Nayaka enraged him. Anapota marched on Warangal in fury.\n*   **1368 A.D.:** In the ensuing battle at **Bhimavaram** near Warangal, **Kapaya Nayaka lost his life**. Anapota Nayaka went on to conquer Bhongir, Warangal, and Singavaram.\n*   Kapaya Nayaka''s death at Anapota''s hands marked the end of the Musunuri Nayakas; no successors of Kapaya Nayaka are known to history, and Warangal lost its prominence.\n*   Anapota Nayaka, having killed Kapaya Nayaka and conquered his lands, found himself stuck with Kapaya''s old enemy — the **Bahmani Sultan** — and carried on a life-and-death struggle against the Bahmanis until the total annexation of Telangana to the Bahmani Kingdom.", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas-p3", "partName": "Velamas of Rachakonda and Devarakonda (1324–1475 A.D.)", "bodyMd": "### Origins as Kakatiya Subordinates: The Recherla Velama Family\n\nThe **Recherla Velama** (or **Padmanayaka**) rulers rose to prominence in the 14th and 15th centuries; they belonged to the **Velama caste**.\n\n*   They were loyal subordinates of the Kakatiyas until that dynasty ceased to rule following defeat at the hands of Tughlaq prince **Ulugh Khan** in 1323 A.D.\n*   The new southern Tughlaq province (comprising the sultan''s latest conquests) was weak from the start and soon broke into revolts. Foremost among the rebels were the Musunuri Nayakas, **Harihara and Bukka** (from Bellary), and the Rachakonda and Devarakonda Velamas.\n\n**Founder — Betalanayaka:**\n\n*   The founder of the Recherla Velama family was **Betalanayaka**, of the dominant Velama peasant caste.\n*   The _Velugotivari Vamsavali_ describes his rise in the Amanagallu (Nalgonda district) area.\n*   Kakatiya ruler **Ganapatideva (1199–1262 A.D.)** assigned the administration of Amanagallu to him; in return Betalanayaka extended support to the ruler — a tradition continued by his sons **Dama, Prasaditya, and Rudra**, all of whom held important positions under Ganapatideva and later under his daughter **Rudramadevi (1262–1290 A.D.)**.\n*   The Recherla Velamas filled the gap left when the Malyala and Recherla Velama chiefs (prominent under Rudradeva and Ganapatideva) disappeared from active participation; Betalanayaka''s sons filled this gap.\n*   Historian **P.V. Parabrahma Sastry** establishes the role of loyal subordinates like the Recherla Velamas in Kakatiya affairs, referring to \"Rudra, the head of the Recherla Velamas family,\" indicating Betalanayaka had passed the baton to his sons.\n\n**Recherla Rudra under Ganapatideva:**\n\n*   Ganapatideva, after consolidating his throne with the help of loyal commanders **Recherla Rudra** and **Malyala Chaunda**, prepared an expedition to the coastal region.\n*   The Recherla and Malyala chiefs were the oldest of the Kakatiya feudatories.\n*   Following the death of Kakatiya king **Rudradeva** and his brother **Mahadeva** in wars against the Yadavas, Ganapatideva was imprisoned at Devagiri. Nobles revolted, but **Recherla Rudra stayed loyal**, put down the revolt, drove away foreign invaders, and governed the kingdom until Ganapatideva''s return from captivity.\n\n**Under Rudramadevi:**\n\n*   Ganapatideva, having no male heir, nominated his elder daughter **Rudramadevi** as heir; she began ruling as co-regent from **1259–60 A.D.** under the name **Rudradeva Maharaja**.\n*   Some royal family members revolted against the queen. She managed to overcome this with the help of loyal supporters, including the Kayastha chiefs **Jannigadeva** and his younger brother **Tripurari**, and the Velama chief **Prasaditya**.\n*   As per the _Velugotivarivamsavali_, Prasaditya assumed the titles **Kakatiya Rajya Sthapanacharaya** and **Raya Pitamahamka**, as reward for pinning down a \"formidable ring of enemies\" who opposed a woman ruler.\n*   His brother **Rudra** also held a high position in the Kakatiya queen''s court.\n*   The third Recherla brother, **Dama Nayudu**, looked after Amanagallu''s affairs. The _Velugotivari Vamsavali_ says he acquired the titles **Khadganarayana, Rayagaya Govala, Bhujabala Bhima**, and **Pratiganda Bhairava** — though no other literary/epigraphic source confirms this.\n\n**Prasaditya and the Nayamkara system:**\n\n*   Prasaditya was appointed a **Nayaka** under the _Nayamkara_ system that came to fruition under Ganapatideva; he is said to have been entrusted defence of the kingdom as one of a group of **77 Nayakas**.\n*   The author of _Pratapacharitra_ credits **Prataparudra** (Rudramadevi''s successor) with introducing the Nayamkara system, implying it did not exist before — but inscriptions refer to _Nayamkara_/the office of _Nayaka_ as early as **1279 A.D.**, contradicting this.\n*   Therefore, Prasaditya seems to be the first Recherla to have received the title, rights, and duties of a _Nayaka_ under the Nayamkara system, during Rudramadevi''s reign. He remained loyal both to her and to her grandson/successor **Prataparudra**, whom he helped strengthen the kingdom in his early years.\n\n**From Dama''s line to independence:**\n\n*   No direct descendants of Recherla Rudra or Prasaditya are known; **Vennama Nayaka** and **Sabbi Nayaka** succeeded their father Dama.\n*   Vennama Nayaka appears in the **Ainavolu inscription**. The _Velugotivarivamsavali_ records a battle he fought against the Delhi Sultanate — likely during **Alauddin Khilji''s first invasion of Telangana in 1303 A.D.**, when he sent an army under Malik Fakruddin Ulugh and Malik Jajju of Karra. The Kakatiyas lost a large army in this battle, in which **Sabbi Nayaka** also fought alongside his brother.\n*   Vennama Nayaka and Sabbi Nayaka each had a son — **Erra Dacha** and **Nalla Dacha** — who were also loyal to the Kakatiyas and distinguished themselves for Prataparudra in a war against the **Pandyas of Madura**. As a mark of appreciation, Prataparudra conferred on Erra Dacha the titles **Pandyadalavibhala** and **Pandyaraya Gajakesari**.\n*   From among the progeny of Erra Dacha — **Singama Nayaka, Venna Nayaka, and Echa Nayaka** — emerged the first independent Reche' WHERE chapter_slug = 'telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas';
UPDATE theory_content SET concepts_json = concepts_json || 'rla Velamas ruler, **Singama Nayaka (I)**.\n\n**Context of independence — post-1323 unrest:**\n\n*   By 1323 A.D., Warangal fort had fallen to Tughlaq prince Ulugh Khan, who conquered much of Telangana and beyond before returning to Delhi.\n*   The repressive new administrative setup left behind by Ulugh Khan gave rise to deep-seated unrest, giving rise to local rebel leaders, among whom the Recherla Velamas emerged as a successful regional power group in the Rachakonda and Amanagallu areas under Singama Nayaka I.\n\n### Singama Nayaka I (1325–1361 A.D.)\n\nThe capital from which Singama Nayaka I ruled is a matter of some controversy.\n\n*   The _Velugotivari Vamsavali_ states that Singama Nayaka I, son of Erra Dacha, lived in Rachakonda and Devarakonda during the time of Prataparudra — but this lacks confirmation, and this area lies 60 miles from Amanagallu (the hereditary village given to founder Betalanayaka by Ganapatideva).\n*   The _Velugotivarivamsavali_ (the primary authority for Recherla Velama history) does not mention Rachakonda at all until the time of Singama Nayaka I''s son and successor, **Anapota Nayaka**. It states that Anapota Nayaka and **Mada Nayaka** (Singama Nayaka I''s second son), after returning from a victorious campaign, ruled Amangallu and divided Rachakonda and Devarakonda between themselves — evidence that Rachakonda was already in Recherla Velama possession even before Anapota''s time.\n*   Another statement, from the _Rasarnava Sudhakaram_ (a work on rhetoric written by Anapota Nayaka''s son, **Singama Nayaka II**), states that **Rajachala/Rachakonda** was the hereditary capital of the Recherla Velama family.\n*   These references indicate Rachakonda came into Recherla possession much earlier, probably during the time of Singama Nayaka I, who must have built a fort there. It probably became the primary capital only from Anapota Nayaka''s time, later becoming a stronghold of the family.\n\n**Reign — territorial expansion:**\n\n*   Singama Nayaka I''s rule began in turbulent times, with the overthrow of Tughlaq authority.\n*   While Musunuri Kapaya Nayaka was engaged in battle with the Bahmanis (1359–61 A.D.), Singama Nayaka I used the opportunity to extend his kingdom as far as Eleshwaram on the banks of the Krishna, seizing forts in the Krishna–Tungabhadra doab.\n*   He came into conflict with the **Chalukya princes**, who sought help from the **Reddys of Kondavidu** to stop his aggressive attacks.\n*   Undaunted, Singama Nayaka I seized the fort of **Jallipalli** (near Khammam), then under Chalukya control, where his brother-in-law **Chintapalli Singama Nayaka** had been imprisoned by the Chalukya princes during the ongoing battles.\n*   To free Chintapalli, Singama Nayaka carried out a vigorous attack on Jallipalli fort. The Chalukya princes, unable to hold the fort, resorted to treachery and had **Singama Nayaka I assassinated** by one **Tambalajiyya**.\n*   Following the assassination of Singama Nayaka I, his enraged descendants seized the fort of Jallipalli and massacred all the kshatriyas and their allies lodged there, in 1361 A.D.\n\n### Anapota I (1361–1383 A.D.) and Mada I (1361–1384 A.D.)\n\nSingama Nayaka I''s sons **Anapota I** and **Mada I** first avenged their father''s death and assumed the title **Somakula Parasurama**.\n\n*   **Anapota I** ruled from **Rachakonda** (also known as Rajukonda); he placed his brother **Mada I** on the throne of **Devarakonda** to secure that region.\n*   After avenging his father, Anapota I modified the fort of Rachakonda to make it impregnable. Three inscriptions of Anapota I, all dated **1365 A.D.**, record construction of a stone fort, a reservoir called **\"Anapota Samudra,\"** and defences to protect the fort.\n\n**War with Kapaya Nayaka and expansion:**\n\n*   Anapota I and Mada I headed north and attacked Musunuri Kapaya Nayaka for control of Warangal fort, **defeating and killing him at the Battle of Bhimavaram (1368 A.D.)** near Warangal.\n*   Anapota I then conquered the forts of **Tribhuvanagiri (Bhuvanagiri)** and **Sanigaram**, among other minor Telangana forts — campaigns recorded in his inscription at **Ainavolu** near Warangal, inscribed on the occasion of his victory over the entire Telangana region.\n*   By **1369 A.D.**, the kingdom of Rachakonda extended to the **Krishna and Tungabhadra in the south** and **Sanigaram** (in modern Karimnagar district) in the north.\n*   After this series of victories, Anapota I placed his brother **Mada Nayaka I** at Devarakonda to protect the south-eastern parts of the kingdom; Mada I and his successors ruled the territory around Devarakonda, which became the **second capital** of the Recherla Velamas.\n\n**Conquest of Kondavidu territory south of the Krishna:**\n\n*   Anapota I and Mada I, along with their cousin **Naga** (son of Yachama Nayaka), invaded the Reddy kingdom of **Kondavidu**.\n*   The _Velugotivari Vamsavali_ states that Mada Nayaka and Anapota Nayaka defeated **Anavema Reddy** of Kondavidu at **Dharanikota**.\n*   Following this victory, Anapota I and Mada I crossed the Krishna and conquered the region to its south (areas in modern Kurnool and Guntur districts); parts of the Reddy kingdom on the southern banks of the Krishna, particularly around Srisailam (now Kurnool district), were annexed — corroborated by epigraphic evidence.\n*   The _Rasarnava Sudhakaram_ states Mada I constructed a flight of steps to the sacred mountain of **Sriparvatam**, making it accessible to pilgrims from Telangana — indicating Sriparvatam was part of their kingdom. This is supported by an inscription of Mada I at **Jatararevu** near Srisailam, stating the steps were built for the convenience of pilgrims from Telangana.\n*   The joint rule of the two brothers marked the **climax of Recherla Velama power** in Telugu country. By **1384 A.D.**, the kingdom extended south of Devarakonda:\n    *   The inscription of Mada I at **Umamaheshwaram** states his rule extended between Srisailam and the Vindhya mountains.\n    *   The inscription of Anapota at **Simhachalam** indicates the coastal campaigns of the Recherla Velamas went up to Simhachalam — though they could not annex any part of coastal Andhra, which remained under Recherla Velama control only prior to the extension of Bahmani rule into Telangana.\n\n### Singama Nayaka II (1383–1399 A.D.) and Vedagiri I (1384–1410 A.D.)\n\nAnapota I and Mada I were succeeded by their sons — **Singama Nayaka II** (at Rachakonda) and **Vedagiri I** (at Devarakonda) respectively.\n\n*   **Singama Nayaka II**, also known as **Sarvajna Singa Bhupala**, was a great scholar and poet; he composed two important Telugu-literature-related Sanskrit works, _Rasarnava Sudhakaram_ and _Ratnapanchalika_.\n*   His cousin **Vedagiri I** maintained close relations with the Rachakonda chiefs and ruled Devarakonda from **1384 to 1410 A.D.**\n\n**Conflicts with Vijayanagara and the Reddys:**\n\n*   In the conflicts between the Reddys and Velamas, the Vijayanagara rulers supported the Reddys, which pushed the Recherla Velamas toward closer ties with the Bahmani kingdom.\n    \n*   This alliance proved useful when the Vijayanagara ruler attacked Singama Nayaka II but was successfully repelled with Bahmani help — this battle was called the **Battle of Kottakota**; the Vijayanagara army chief **Saluvaraya died** in this battle.\n    \n*   An epigraph dated **1387 A.D.** at Simhachalam suggests the Recherla Velamas invaded the Reddy dominion during the early years of the reign of **Kumaragiri Reddy**.\n    \n*   Singama Nayaka II and his cousin Vedagiri I decided to conquer the northern districts of the Reddy kingdom by taking advantage of the succession tussle between **Peda Komativema Reddy** and Kumaragiri Reddy.\n*   While the Recherla Velama chiefs were engaged in coastal Andhra with the Reddys of Rajahmahendravaram, **Bukka II of Vijayanagara** attacked and occupied the fort of **Panugal** (Mahbubnagar district) and **Warangal fort**, a strategic Recherla Velama possession, in **1397 A.D.**\n*   With the help of the Bahmani ruler **Firoz Shah**, Singama Nayaka II and Vedagiri I put up strong resistance, but this time **lost to Vijayanagara**.\n*   Singama Nayaka II and Vedagiri I also came into conflict with the **Gajapatis of Orissa**, as indicated by the latter''s inscriptions at **Srikurmam** (Srikakulam district) and at **Simhachalam**.\n\n### Anapota II (1399–1421 A.D.), Rao Madanedu, and Mada Nayaka II (1421–1430 A.D.)\n\nIn **1399 A.D.**, Singama Nayaka II was succeeded by his sons **Anapota II** and **Rao Madanedu**. At the same time, **Mada Nayaka II** succeeded his father Vedagiri I at Devarakonda.\n\n*   Their reigns saw a series of wars with the Reddys, the Vijayanagara Rayas, and finally the Bahmanis.\n*   They provoked conflict with the **Reddys of Rajahmahendravaram (Rajahmundry)** by offering asylum to **Annadeva Choda**, a lower-Godavari chief driven out of his dominions by these Reddys.\n*   Madanedu of Devarakonda defeated the Reddys and annexed Annadeva Choda''s dominion — but **Pedakomati Vema Reddy**, with Bahmani help, soon restored the lost territory to Annadeva Choda.\n*   The **Bahmani army led by Sultan Firoz Shah attacked Panugal fort**; this time **Singama Nayaka \\[II''s successors\\] and Vijayanagara joined together**, marched a combined army against the Bahmanis, and defeated them.\n    *   In this battle (**1419 A.D.**), **Macha Reddy**, brother of Pedakomati Vema Reddy, was killed.\n*   Following this defeat, the Recherla Velamas, allied with Pedakomati Vema Reddy, attacked Devarakonda and killed Vedagiri. Soon after, in 1420 A.D., the Velamas killed Pedakomati Vema Reddy and hanged him at the entrance of Devarakonda fort. After this war, the Reddy kingdom of Kondavidu virtually disappeared from the political scenario of Andhra.\n    \n*   After Anapota II, his brother **Rao Madanedu** ascended the throne as regent at Rachakonda, since Anapota''s son **Singama Nayaka III** was too young to be king.\n*   Rao Madanedu and his brothers — **Dacha, Vallabhanedu, Vedagiri, and Damanedu** — helped the young king in wartime and daily administration.\n*   **Rao Madanayaka** (younger brother of Anapota II), also called **Kumara Anapota**, ascended the throne at Rachakonda in **1423 A.D.**\n\n### Singama Nayaka III/Sarvagna Rao and Lingama Nayaka (1430–1475 A.D.)\n\nIn **1425 A.D.**, Anapota II was succeeded by his son **Singama Nayaka III**, and Mada II was succeeded by his son **Vedagiri II** and **Lingama Nayaka** at Devarakonda.\n\n*   **Decline of the kingdom:** during this period, Rachakonda witnessed decline.\n    *   The **Bahmanis of Bidar** occupied the forts of Medak, Warangal, and Bhuvanagiri during **1433–38 A.D.**\n    *   What happened to Singama Nayaka III subsequently is not known; he probably retired to **Bellamkonda** in Guntur district, where he appears to have led an eventful life till **1455 A.D.**\n    *   Except for Devarakonda, the rest of the Recherla Velama kingdom was subjugated by the Bahmanis.\n\n**Lingama Nayaka''s revival via Orissa alliance:**\n\n*   **Lingama Nayaka** (known as Lingamanedu), unable to resist Bahmani attacks, sought the help of the Orissa rulers.\n*   Because of the Velamas'' weakness, Kapileshwara Gajapati of Orissa readily accepted Lingama Nayaka''s request and sent a large force to Devarakonda against the Bahmanis.\n*   Lingama Nayaka **reoccupied his lost territories such as Orugallu and Bhuvanagiri in 1461 A.D.**, becoming a vassal of the Gajapatis of Orissa on account of this help — corroborated by inscriptions of Kapileshwara Gajapati.\n*   **Rao Dharma Rao**, son of Lingama Nayaka, was appointed to rule over Orugallu.\n\n**End of the kingdom:**\n\n*   The integrity of the kingdom of Rachakonda and Devarakonda came to an end in Lingama Nayaka''s last years.\n*   At the death of **Kapileshwara Gajapati in 1470 A.D.**, conflicts arose between his sons **Purushotama Gajapati** and **Kumara Hamvira Gajapati** for the throne.\n*   Taking advantage of this Orissa succession conflict, the Bahmani Sultan Muhammad Shah II defeated Lingama Nayaka and occupied Rachakonda and Devarakonda.\n*   After Lingama Nayaka, his brother **Suranedu**, son **Parvata Rao**, and grandson **Lingama Nayaka II** ruled over Devarakonda for some time as subordinates of the Bahmanis, paying annual tribute; later they came under the yoke of the **Vijayanagaras**.", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas-p4", "partName": "Inter-State Relations of the Velamas", "bodyMd": "The Velamas of Rachakonda and Devarakonda ruled the entire Telangana as a successful \"Regional Power\" for **one and a half centuries**, playing an active role in contemporary politics.\n\n*   Since the kingdom was situated amidst the **Bahmanis of Gulbarga** (west), **Rayas of Vijayanagara** (south), **Reddys of Kondavidu** (east), and **Gajapatis of Orissa** (north), the Velamas had to contend with these neighbours to stabilise and extend their power — hence they often shifted alliances in the troubled waters.\n\n### Relations with Bahmanis of Gulbarga\n\nDuring the early rule of the Velamas, relations with the Bahmanis were cordial — **Bahaman Shah I** helped **Anapota Nayaka I** against Kapaya Nayaka. Cordial relations continued through Singama Nayaka II and Vedagiri I.\n\n*   During the reigns of Anapota II and Mada II, when they were at war with the Reddys, Feroz Shah II attacked and besieged Panugal fort (1417 A.D.), which ended the friendly relationship; Anapota II cut off the traditional policy of loyal friendship with the Bahmanis and joined hands with the Vijayanagara.\n*   The unfriendly attitude continued till the end of the Velamas.\n*   During the reigns of **Sarvagna Rao Singama Nayaka III and Lingama Nayaka**, the Bahmani Sultan **Ahmad Shah II** attacked the forts of Orugallu, Bhongir, Rachakonda, and Devarakonda and seized wealth. This ultimately resulted in the **subjugation of the Velamas** to vassalage under the Bahmanis and, finally, the Vijayanagaras.\n\n### Relations with Reddys of Kondavidu\n\nRelations between the Velamas and Reddys were never cordial from the outset.\n\n*   Since the Reddy kingdom was a doab with rich, fertile rice-yielding soils on the coast, while the Velama kingdom was an arid zone, the Velamas'' eyes were fixed on the Reddys'' coastal territory, making conflict inevitable.\n*   The _Velugotivari Vamshavali_ refers to Velama–Reddy conflicts that ended with no material benefits to either party, except giving scope for **Bahmani and Vijayanagara intervention** in their political affairs.\n\n### Relations with Rayas of Vijayanagara\n\nThe political alliances between the Velamas and Vijayanagara kings were fluid and temporary.\n\n*   When Singama Nayaka I and Vedagiri were engaged in war with the Reddys in coastal Andhra, Bukkaraya II atta' WHERE chapter_slug = 'telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas';
UPDATE theory_content SET concepts_json = concepts_json || 'cked Panugal fort, taking advantage of their absence in Telangana — resulting in the outbreak of rivalry between the two parties.\n*   Vijayanagara''s intervention into Reddy–Kondavidu affairs prevented the Velamas'' coastal campaigns. The last powerful ruler, **Lingama Nayaka**, who attempted to win Vijayanagara territories, ended his career in failure.\n\n### Relations with Gajapatis of Orissa\n\nRelations between the Velamas and Gajapatis of Orissa were friendly and cordial.\n\n*   The early reign of **Anapota I** and his brother''s son **Vedagiri** extended as far as Srikurmam and Simhachalam, in the process of kingdom extension.\n*   During the last phase, under **Lingama Nayaka**, **Kapileshwara Gajapati of Orissa** came to assist the Velama chief of Devarakonda to overcome the invasion of **Humayun Shah** of the Bahmani dynasty; the Orissa rulers came forward as far as Orugallu, supported by epigraphs laid down by the Orissa rulers at that fort.\n*   Thereafter, the Velamas of Rachakonda and Devarakonda acted as subordinates to the Gajapati rulers, owing to their assistance sought in their wars with the Bahmanis.", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas-p5", "partName": "Administrative System of the Velamas", "bodyMd": "Main sources for the polity of the Velamas period in Telangana include contemporary Telugu works: _Sakala Niti Sammatamu_ (Madiki Singana), _Rukmangada Charitra_ (Praudha Kavi Mallana), _Kridabhiramamu_ (Srinatha), _Bhaskara Ramayanamu_, _Harivamsamu_ (Erra­preggada), _Pratapa Charitra_ (Ekambranatha), and _Siddhesvara Charitra_ (Kase Sarvappa). These furnish material on polity, administration, offices (civil and military), taxation, war and peace, forts, and espionage.\n\n*   The _Velugotivari Vamsavali_ also deals with the history of the Recherla Velamas.\n*   Between **1323–1475 A.D.**, all the kingdoms were guided by the theory of _**saptanga**_ — the seven constituent elements of sovereignty enjoined by **Kautilya**: king, minister, land, fort, treasury, army, and friend.\n*   Contemporary Telugu works on polity also emphasized this theory:\n    *   _Andhra Kamandakamu_ (cited by Singana) also emphasizes _saptanga_.\n    *   _Rukmangada Charitra_ lists: _pati_ (king), _amatya_ (minister), _durgamu_ (fort), _kshiti_ (land), _mitra_ (friend), _dhanamu_ (treasury), and _sena_ (army).\n\n### Saptanga in Practice\n\n**The King:**\n\n*   Monarchy was the order of the day; the king was the supreme head of state, expected to govern without fear or favour per the _dharma sastras and smritis_.\n*   Post-Kakatiya kings did not assume regal titles signifying kingship (unlike their Kakatiya masters) — the Musunuri and Velama kings omitted the epithet _mahamandaleshwara_ from their _prasasti_.\n\n*   Because they belonged to the _chaturthakula_ (fourth caste), the Hindu dharma sastras did not permit them regal titles, as they did not belong to the kshatriya caste claiming descent from the Sun god or Moon god.\n\n*   According to contemporary literature, the king was expected to be well-educated, and to maintain cordial relations with other ruling chiefs.\n*   **Madiki Singana** draws a verse from _Kumara Sambhavam_ enjoining the king to be thorough in the _sapta upayas_ (seven strategies):\n    *   _Samamu_ (conciliation)\n    *   _Bhedamu_ (creating a division)\n    *   _Danamu_ (charity)\n    *   _Dandamu_ (punishment)\n    *   _Maya_ (deception)\n    *   _Upeksha_ (ignoring)\n    *   _Indrajala_ (magic)\n*   The king was also expected to possess sharp intelligence, strong memory, foresight, knowledge of warfare, and to strictly maintain _varnasrama dharma_.\n*   _Rukmangada charitra_ prescribes the art of riding elephants, horses, and chariots, and wielding different weapons, besides studying _natya_ (dance), _kavya_ (literature), _alankara sastra_ (rhetoric), and histories as laid down in the _Puranas_ and _Itihasas_.\n*   An examination of inscriptions reveals **Musunuri Kapaya Nayaka** was an expert in statecraft, had a _Vimala charita_ (spotless character), and was authoritative in the observance of _dharma karmas_. Among the Recherla Velamas, **Sarvagna Singa Bhupala** was a great scholar who wrote _Rasarnava Sudhakaram_.\n*   As prescribed by law, the king was to rule with justice and morality:\n    *   The _Velugotivari Vamsavali_ states a king must, like Lord Rama of the _Ramayana_, evoke the faith and confidence of his subjects.\n    *   The _Rukmangada charitra_ states a king who rules without morality and justice would be deprived of his wealth and become destitute.\n*   **Succession** was normally hereditary, based on the law of **primogeniture** (succession by the eldest); however there were a few instances of succession by brothers or cousins, as with **Musunuri Prolaya Nayaka**, succeeded by his brother Kapaya Nayaka, and **Peda Komati Vema**, succeeding his uncle Komaragiri after the death of his son Anavota II.\n*   There appears to have existed a kind of joint rule or _**dvairajya**_ by the king and the crown prince (_yuvaraja_), probably meant to impart practical administrative training to the crown prince. _Sakala Niti Sammatamu_ states the _yuvaraja_ and the minister (_amatya_) were like the two shoulders to the king.\n\n**The Minister:**\n\n*   The minister (_mantri_) stood next in importance to the king. Matters of importance prescribed that a king hold consultations with a minister or council of ministers.\n*   The council was generally to comprise:\n    *   **12 members** according to Manu\n    *   **16** according to Brihaspati\n    *   **20** according to _Sukranitisara_\n*   **Mallana** warns the king not to rely entirely on the minister''s advice — if the king entrusts the kingdom to the minister''s care without personally looking after affairs, the minister will become the master in due course.\n*   The head of the council of ministers was called _**pradhani**_; other members were called _**mantrins**_.\n*   Mallana prescribes qualities required of a minister: _**suddhi**_ (righteousness), _**buddhi**_ (wisdom), _**santi**_ (composure), _**vriddhacharamu**_ (tradition), _**vivekamu**_ (discrimination), _**sraddha**_ (devotion), _**dhairyamu**_ (courage), and _**prabhu buddhi**_ (loyalty).\n*   Almost all works on polity state that only **Brahmans** should be appointed as ministers.\n\n**The Fort:**\n\n*   The fort held the next place of importance. **Madiki Singana** devotes a chapter titled _Durga Samrakshanamu_ in his _Sakala Niti Sammatamu_, discussing kinds of forts, methods of attack and defence, and garrison.\n*   He cites a verse from _Kamandakamu_: a king should take refuge in a fort like a tiger in the bushes, an elephant on the hilltop, and a lion in the cave; a king requires a strong fort on high mountain cliffs or in a dense forest, like Lord Vishnu whose abode is the deep ocean, or Siva on the high Himalayas.\n*   _Purushartha Sara_ compares a king without a fort to an elephant without rut and a serpent without poison.\n*   Singana prescribes several artificial contrivances to strengthen forts: a high rampart (_prakara_), towers (_gopura_), and bastions (_attalaka_ and _kottala_).\n*   The garrison should contain plenty of grains, wealth, water, men, material, wood, machines, weapons of war, and strong entrance/exit gateways.\n*   **Mallana** emphasizes forts and prescribes as essential: _kota_ (_prakara_), _agadta_ (moat), _attada_ (tower), _gavani_ (gateway), and _kavata_ (doorframe).\n*   Forts of the post-Kakatiya period belonged to all four kinds mentioned:\n    *   **Land forts** (_sthala durgas_): **Warangal**\n    *   **Hill forts** (_giri durgas_): **Devarakonda and Bhuvanagiri**\n*   Forts enjoyed a prominent place in the Recherla and Devarakonda Velamas'' kingdom, evident from titles borne by various kings — e.g., the **Draksharama inscription of Anapota** calls him _Dvipijeta_.\n*   Rachakonda, Devarakonda, and Bhuvanagiri were the main **hill forts** of the Recherla Velamas; Orugallu, Amanagallu, Anathagiri, Aruvapally, Podichedy, Anumula, Pangal, and Jallipalli were their **land forts**.\n\n**Land or Territory:**\n\n*   A king is not worth the name without territory. Kautilya accords it third place in order of importance. Contemporary Telugu works call it _rashtra_. **Mallana** assigns it fourth place and calls it _Kshiti_, advising a king to protect his land effectively from enemy attacks and not turn his back.\n\n**Mitra (Friend):**\n\n*   Kautilya assigns suitable friends the seventh place; contemporary Telugu works place it fifth in priority. \n*   In practice, the Rachakonda and Devarakonda Velamas, considering the size and strength of their kingdoms, entered into matrimonial alliances and friendship with one superpower or another — either the Rayas of Vijayanagara or the Bahmanis of Gulbarga — to save themselves.\n\n**Treasury:**\n\n*   Kautilya places the royal treasury fifth in importance, but Telugu works stress the king should not extract more money than needed — likened to \"eating the fish after excavating the tanks.\"\n*   While information specific to the Musunuri and Rachakonda/Devarakonda Velamas is not directly available, **Madiki Singana** and **Mallana** provide information on state income sources:\n    *   _**Kshiti pancham**_ (produce of the land paid by the farmer to the king), termed _**arambamu**_\n    *   Taxes: _**karamu, kappamu, ari**_ and _**appanamu**_\n    *   _**Illari**_ — taxes on houses\n    *   _**Vritti katnalu**_ — taxes on looms, oil mills, etc.\n    *   _**Pullari**_ — taxes on pasture, lands\n    *   _**Sunka**_ — taxes/duties on import of trade articles\n\n**The Army:**\n\n*   This occupies **sixth** place in Kautilya''s _saptanga_ theory, but Telugu works place it in **seventh** position.\n*   The army was based on the traditional _**chaturangabala**_: infantry, cavalry, elephant, and chariots (chariot design/draught animal is not known).\n*   An inscription of the Velamas reveals the infantry consisted of **four divisions**:\n    1.  _**Selagola**_ — javelin/spear-bearers\n    2.  _**Vilukandru**_ — archers/bowmen\n    3.  _**Kaijitagandru**_ — warriors/soldiers who drew salaries daily or weekly\n    4.  _**Ekkati**_ — a soldier kept in reserve, capable of handling heavy weapons like maces\n*   Weapons in vogue: sabres, daggers, maces, javelins, spears, battle axes, discs, and _pashana yantras_ (catapults). The shield was known as _arige_ or _dalu_.\n*   Military generals were known by different names: _padinayaka, padalu, dalavayi,_ and _dandanayaka_. The _Velugotivari Vamsavali_ mentions _padinayakas, biruda rahuttas,_ and _lenkas_.\n\n### Administrative Divisions\n\nThe Rachakonda and Devarakonda Velama kingdoms were divided into administrative units: _**bhumi, nadu, sthala,**_ and _**grama**_ (village).\n\n*   The village formed the basic unit of administration.\n    *   _**Talari**_ — head man of the village\n    *   _**Karanam**_ — village accountant, maintained land records and tax rates for arable, waste, cultivated, fallow, wet, and dry lands\n    *   _**Bari kapu**_ — village policeman; maintained boundaries and guarded fields from wild beasts and thieves\n*   Other officials:\n    *   _**Kavile sampratis**_ — record keepers who maintained registers of royal orders on revenue and expenditure\n    *   _**Rayasams**_ (or _vrayasa_) — scribes/private secretaries to the king; required to be quick in hand, write many scripts, and be proficient in various languages", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas-p6", "partName": "Social Conditions", "bodyMd": "Social mobility generally occurred in two phases: first, the lowest castes and tribes were **sanskritized**; second, the sanskritized people were drawn into caste society as **Sudras**.\n\n*   The service of **Brahmans** was essential for this mobility — they brahmanised Desi culture on one hand, and on the other provided lineages to rulers, legitimizing them as Kshatriyas and stabilizing their ritual hegemony.\n*   The **Varna structure** in the period is tripartite: Brahmans, Vaisyas, and Sudras (no Kshatriya institutions existed in medieval South India).\n\n### The Brahmans\n\nThe Brahmans, per _Purusasukata_, were said to be born from the head of _Viratpurusa_, and were theoretically the _agra varna_ in contemporary Dharma Sastras and inscriptions.\n\n*   Their ritual purity, determined by birth, elevated their position as pace-makers and legitimizers of ruling power.\n*   Brahmins were expected to perform:\n    *   **Panchayajnas**: _Pitru Yajna_ (worship of ancestors), _Guru Yajna_ (worship of priests), _Evan Yajna_ (worship of God), _Brahma Yajna_ (worship of Brahmins), _Go Yajna_ (worship of cows)\n    *   **Shatkarmas**: _Yajna_ (sacrifice), _Yajana_ (priest to the sacrifice), _Svadhyaya_ (self-study), _Adhyapana_ (teaching), _Danam_ (donation), _Pratigrahana_ (accepting donation)\n    *   Austerities: _yama, niyama, dhyana, dharana, mouna, anushta,_ etc.\n*   Whenever forests were cleared, new villages were formed and donated to Brahmins as _agraharas_ — a practice extensively done in Kakatiyan times as part of economic policy.\n*   Meanwhile, pastoral communities (**Gollas, Kurumas**) and tribes (**Pulindas, Koyas, Boyas**) were drawn into caste society as Sudras; the Brahmins brahmanized their deities and identified them with the Hindu pantheon.\n*   Kings gave _agraharas_ to Brahmins in newly conquered provinces so they could act as pace-makers with the people and legitimize royal rule — an exchange of material resources for royal honours.\n*   Notable Brahmin families in Kakatiya strategic posts: **Gangadhara, Tikkana, Sivadevaiah, Induluri, Bendapudi**.\n*   Under **Mada Nayaka I (1361–1384 A.D.)**, the Brahmin minister **Potanamatya** was regarded as _Rajyangaika durandhrah_ (expert in statecraft), _Sarvasastra visarada_ (scholar in different branches of learning), _Kavivaa_ (best among poets), and _Sthotraika patrikrutam_ (only person eligible for flattering \\[the king\\]).\n*   There was a shift in the Brahmins'' conception of role in society, reflected in professional mobility; sectarianism among Brahmins was not yet highly deep-rooted.\n*   With the reduction of _agraharas_ and the extensive appointment of Brahmins in royal courts, a gulf broadened between the **Vaidika Brahmins** (teaching/priestly professions) and the **Niyogis** (secular duties).\n\n### Kshatriyas\n\nThere was a total absence of formal Kshatriya institutions in medieval South India; the dharma/duty of Kshatriyas was to protect and rule the people.\n\n*   Peasant warrior families that dominated South India in the medieval period gradually became rulers of the land, called **sat-Sudras** because of their pertinence to domestic/ritual engagements — among such Sudras, the **Reddys, Velamas, Kammas** des' WHERE chapter_slug = 'telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas';
UPDATE theory_content SET concepts_json = concepts_json || 'erve mention.\n*   Dominant peasant warrior groups of the early medieval times — the **Rastakutas, Chalukyas, Kakatiyas** — claimed Kshatriyahood after attaining sovereignty; the Rastrakutas, Chalukyas, and Kakatiyas were claimed to be Kshatriyas of the **lunar race**.\n*   Regional/local powers that arose after the fall of the Kakatiya kingdom followed the same practice — the **Chodas of Kandur, Nellore, Konidena, and Pottapi** were said to be Kshatriyas of the **solar race**.\n*   This transmission of political domination associated with the symbol of Kshatriyahood, from central to supra-local/local powers, was common in medieval times.\n*   **Herman Kulke** terms this process **\"Kshatriyaization\"** — the sat-Sudra families/dominant peasant warrior groups, in the process of agrarian expansion, attained political power and claimed Kshatriyahood to stabilize their newly acquired authority, tracing their lineage to mythical races.\n*   It is interesting that the **Velamas**, who emerged as a regional power in post-Kakatiya Telangana, did **not** claim lineage of the solar race — instead they claimed equality with the **Raghu Vamsa**. Their subordinate rulers of **Jallipalli** were called **Soma Vamsa Kshatriyas**.\n\n### The Vaisyas\n\nThe Vaisyas, locally called **Komatis**, were the traditional traders in Telugu country.\n\n*   By the time of the Chalukya-Cholas, the Vaisyas of coastal Andhra were organized into a caste-cum-professional guild known as **''Nakaram''** at eighteen different places, with headquarters at **Penugonda** in West Godavari district.\n*   During Kakatiyan times, the Vaisyas were organized into _Desi, Nanadesi, ubhaya nanadesi, Nakaras_ dealing with different items ranging from grain to elephants, as trade span increased.\n*   The Vaisyas had to compete with **Balijas**, mentioned in records as _Balanjasettikandru_; they claimed themselves as _Virabalanjara dharma Pratipalitulu_ and were organized into another guild called **Pekkandru** (itself indicating an itinerant guild).\n*   The Vaisyas'' profession was proliferated by these Balijas; by the 15th century the Vaisyas had become part and parcel of the Pekkandru guild — indicating decline in the itinerant nature of Vaisya trade, and that their profession was proliferated by Sudra-varna.\n\n### The Sudras\n\nThe Sudras, constituting the bulk of the population, ranged from **sat-Sudras to Panchamas**, divided into right-hand and left-hand communities:\n    *   **Right-hand community / sat-Sudras**: engaged in clean/agricultural operations — included the Velamas, Kammas, and Reddy communities, segregated on lineage and territorial basis\n    *   **Left-hand community**: the others\n*   Among **Kapu**, there were **14 branches** organized territorially:\n\n| # | Branch | # | Branch |\n|---|---|---|---|\n| 1 | Pakanati | 8 | Nereti |\n| 2 | Velanati | 9 | Bhumanci |\n| 3 | Motati | 10 | Desati |\n| 4 | Morasa | 11 | Ayodhya |\n| 5 | Pongalinati | 12 | Oruganti |\n| 6 | Munnuti | 13 | Kuriceti |\n| 7 | Panta | 14 | Gandikota |\n\n*   They claimed themselves as the **settis**. The **Panchnamvaru**, who dealt with carpentry, pottery, blacksmithing, masonry, and goldsmithing, claimed their origin from the five faces of Brahma and claimed equality with the Brahmins, as revealed by their elaborate _prasastis_.\n*   **Tambalas** were another community, most of whom were saints who followed austerities such as purity and pollution, and performed the duties of priests, also claiming equality with the Brahmins. In the famous **Ayyanavolu temple**, the priests are Tambalas.\n    *   In the left-hand communities, social mobility is \"vertical and group-wise,\" unlike among the sat-Sudras, where mobility was family-wise or individual.\n\n### The Panchamas\n\nThe Panchamas constitute **Malas** and **Madigas**.\n    *   **Malas** — constituted agricultural labour\n    *   **Madigas** — prepared accessories for agriculture\n*   Both lived in the outskirts of villages, but sometimes actively participated in fairs and festivals of village gods/goddesses. In the **Ekavira temple**, during festival times, Mala ladies played a very prominent role. The Madigas were employed for executing animal sacrifices. Ritually they were incorporated into society through temples and festivals.\n\n### The Tribals\n\nTribals included **boyas, pulinda, koyas,** and **lambadis**; among pastoral communities, **gollas** and **kurumas** deserve mention.\n\n*   The **Gollas and Kurumas** were dominant communities in this region; their gods **Birappa** and **Mallanna** were equalized with Lord **Mallikarjuna of Sriparvata**.\n\n### Women''s Position\n\nThe Vedic style of family was based on the docility and submissiveness of women; unquestioning obedience on the wife''s part was held up as the supreme virtue of womanhood.\n\n*   The _Rukmangada Charitra_ states that a woman should not be angry even if her husband desires the company of another woman — she should please both by her behaviour. If the husband dies, she should jump into the funeral pyre.\n*   **The widow** was perhaps the most miserable of all — an object of ridicule, a victim of insults and injuries. The law ignored her; society spurned her; per the law, her blessings were considered poison and none should accept them.\n*   Contemporary works praised to the skies wives who committed **Sati** and condemned those who preferred to live. Examples:\n    *   **Peradevi**, wife of Alaraju, committed Sati when her husband was poisoned to death by Nayakuralu of Palanadu.\n    *   **Rati Devi**, wife of Manmatha, asked for a funeral pyre to be prepared for herself and her husband, when the latter was turned to ashes by Siva.", "free": false}, {"partNumber": 7, "conceptId": "telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas-p7", "partName": "Religious Conditions", "bodyMd": "During the Velama regions of Rachakonda and Devarakonda, the era witnessed the growth of **Saivism and Vaishnavism** in Telangana.\n\n*   During Kakatiya times, **Maktal, Borugadda, and Lingagiri** were centres of Vaishnavism.\n*   The growth of the Vijayanagaras, who patronaged the Chennakeshava cult, would have necessitated the Velama kings to also extend patronage to the Vaishnava cult in this region.\n*   The Velama kings of Rachakonda and Devarakonda had links with the **Vaishnavate acharyas of Srirangam Desika**; perhaps **Vedanta Desika** of Srirangam was preceptor of **Venna**, son of Mada Nayaka I.\n*   Through the efforts of these acharyas, the two opposite schools of Vaishnavism soon crystallized into two well-defined sects: the **Vadagalai** (northern school) and the **Tengalai** (southern school). **Vedanta Desika** was leader of the Vadagalai school, and **Pillai Lokacharya** the leader of the Tengalai school.\n*   The Velama kings gifted in cash and kind to temples of both Saivite and Vaishnavate cults:\n\n**Gifts to Temples**\n\n| King | Inscription | Gift |\n|---|---|---|\n| Anapota I | Simhachalam temple (1380 AD) | Five Tanks |\n| Singa II | Simhachalam temple (1387 AD) | Tiruvalika kola |\n| Vedagiri I | Simhachalam temple (1404 AD) | Tankalu 80 |\n| Vedagiri I | Srikurmam (1405 AD) | 100 madas |\n| Venna | Kandikonda (1375 AD) | Lands |\n| Mada I | Domalapalli (1367 AD) | Lands |\n| Anapota I | Ayanavolu (1369 AD) | Ayanavolu village |\n| Vedagiri I | Murupunutala (1399 AD) | Murupunutala village |\n| Rao Dharma Nayaka | Sayampet (1469 AD) | 10 vrittis of village Macherla |\n\n*   This shows the Velama kings tried to exchange their \"honours\" with sectarian leaders through temples; the latter became an important component of royal policy. The most important aspect was the construction of **royal temples** or popular cult centres — Velama kings not only constructed new temples but also renovated existing ones:\n\n**Saivate Temples**\n\n| King | Inscription | Temple/Mandapa |\n|---|---|---|\n| Anapota I | Rachakonda (1365 AD) | Bhairava Prastishta |\n| Mada I | Umamaheswaram (1376 AD) | Mandapa |\n| Venna | Kandikonda (1375 AD) | Temple |\n| Anapota | Ayanavolu (1369 AD) | Walls construction |\n\n**Vaishnavate Temples**\n\n| King | Inscription | Temple/Mandapa |\n|---|---|---|\n| Mada I | Domalapally (1367 A.D.) | Chennakesava Pratista |\n| Venna | Kandikonda (1375 A.D.) | Temple |\n\n*   Gifting and renovating established cult centres such as the **Mailara temple of Ayanavolu** and the **Umamahesvaram temple** at Umamaheshwaram reflect the kings'' efforts to stabilize power through ritual policy.\n*   Traditional scholars held that the Velamas were staunch Vaishnavites, extending patronage to Vedanta Desika and constructing new Vaishnavite temples. \n\n*   But the **Ayanavolu inscription** states that **Mailaradeva** was their _Kuladevata_ (tutelary deity) — a contradictory piece of evidence, showing that like other medieval power groups, the Velama kings tried to stabilize their hegemony through royal temple policy, extending patronage to popular cults and centres broadly.", "free": false}, {"partNumber": 8, "conceptId": "telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas-p8", "partName": "Economic Conditions", "bodyMd": "Economic factors play a dominant role in characterizing any given polity.\n\n*   After 1300 A.D., the trend in the economy changed — a shift known in economic nomenclature as ''revival'' — attested by increased money circulation and growth of trade and commerce.\n*   Some inscriptions of the Rachakonda and Devarakonda Velamas refer to monetary grants given to the temples of Simhachalam and Srikakulam:\n\n**Monetary Grants**\n\n| King | Inscription | Grant |\n|---|---|---|\n| Anapota I | Simhachalam temple (1380 AD) | 5 Tankas |\n| Vedagiri I | Simhachalam temple (1404 AD) | 80 Tankas |\n| Vedagiri I | Srikurumam (1405 AD) | 100 Madas |\n\n*   The Simhachalam and Srikakulam inscriptions indicate the clue to economic revival. Prior to Kakatiya rule, most inscriptions issued by feudatories and local chiefs record land donations to temples instead of monetary donations. Post-Kakatiya-period inscriptions issued by feudal lords refer to monetary grants alongside land grants — indirectly reflecting the growth of a monetary economy, negligible in the pre-Kakatiya period, showing signs of revival in the post-Kakatiya age.\n*   The money endowments to temples also indicate enhanced temple investment capability due to the cautious royal temple policy. **Temple economy** under regional power started emerging as an institution for resource mobilization and re-distribution. Temples also received gifts and donations from guilds.\n    *   No inscriptions belonging to the provinces of Rachakonda and Devarakonda Velama kings mention guilds directly, but contemporary inscriptions of regional powers like the Reddys refer to guilds. Guild activity seems to have undergone change, reflecting the revival in the economy owing to increased money circulation.\n*   The growth of trade and commerce resulted in the expansion of agriculture. The Velamas of Rachakonda and Devarakonda, being subordinates of Kakatiyas, followed their footsteps — the Kakatiya rulers had formulated a policy of deforestation and land reclamation for agricultural expansion.\n\n### Geography and Irrigation\n\nThe Telangana region is a **rain shadow area** with a limited river system; even rivers flowing across the region are hardly beneficial for cultivation. There is no big river flowing across Telangana; only the **Krishna** touches its peripheral zones. Rivers **Dindi, Musi, Aleru**, etc., are tributaries of the Krishna.\n\n*   The region ruled by Rachakonda and Devarakonda Velama kings lies mostly in the present-day districts of **Mahaboobnagar and Nalgonda** — districts covered with red soils hardly drained by any river system, remaining waste and producing only wild bushes/shrubs.\n*   Many epigraphs issued by Rachakonda and Devarakonda kings speak of construction of tanks and wells:\n\n**Irrigation Facilities**\n\n| King | Inscription | Irrigation Work |\n|---|---|---|\n| Anapota I | Rachakonda (1365 AD) | Anapota Samudram (tank); 2 Wells |\n| Anapota I | Rachakonda (1380 AD) | Raya Samudram (tank) |\n| Nagambhika Queen of Rao Mada Nayaka | Devulanagaram (1429 AD) | Naga Samudram (tank) |\n| Vedagiri | Sannad (1429 AD) | Vedagiri Tatakamu (tank) |\n| Madhava Rao | Sannad (1429 AD) | Parvata Rao Tatakamu (tank) |\n| Madahava Rao | Sannad (1429 AD) | Madha Rao Cheruvu (tank) |\n\n*   About **20 inscriptions** belonging to Velama kings were found in this region; of these at least four are fragmented. Of the remaining 16, **6 inscriptions** (three of them _sannads_) mention either construction or reconstruction of tanks.\n*   Contemporary epigraphs and literature mention the founding of new villages alongside tank construction; every village was benefitted by a major tank in the region — the tank irrigation system generally resulted in the establishment of nuclear villages.\n\n### Land Tenure and Village Categories\n\n**First category**: villages held directly by the state (central power), where the state collected revenues directly through its own administrative machinery — generally known as _**Bhandaaravada gramas**_ or _**kara**_ villages. The Mohammedan rulers called them **Khalsa** or **Khas** lands/villages, meaning \"crown lands.\"\n\n*   **Second category**: **Nayaka villages**, held by state officials/feudatories rendering military services to the state — situated around the forts of Rachakonda, Devarakonda, Bhuvanagiri, Golconda, Sirikonda, Panugallu, Kolanupaka, Pillalamarri, Hanamkonda, Orugallau, etc.\n    *   These areas were not hereditary, and the emperor could confiscate holdings at any time.\n    *   These feudatories also leased out lands to revenue farmers or _**guttadars**_, though the villagers themselves held most of the land; therefore \"they claimed no property right, nor did they regard the cultivators as their serfs.\"\n*   **Third category**: villages held by groups of people or institutions like temples, paying nothing or a nominal amount as revenue — called _**brahmadeyas**_ or _**devadana**_ lands.\n\n**Brahmadeya and Devadana Land Tenures**\n\n| King | Inscription | Devadana | Brahmadeya |\n|---|---|---|---|\n| Anapota I | Aynavolu (1369 AD) | Aynavolu village | — |\n| Vedagiri | Murupunutala (1399 AD) | Murupunutala village | Land grants |\n| Mada I | Domalapally (1367 AD) | Land grants | Land grants |\n| Venna | Kandikonda (1375 AD) | – | Land grants |\n| Rao Dharma Nayaka | Sayampeta (1464 AD) | Maccerla village and Land grants | Maccerla village and Land grants |\n\n*   It is interesting to note from the above table that the _brahmadeya_ grants, which dominated in Pre-Kakatiyan times, showed a decrease in the post-Kakatiya period, and their place was largely taken over by _devadana_ grants.\n\n### Soil Types and Land Measurement\n\n**Soil Types**\n\n| King | Inscription | Wet Land | Dry Land |\n|--' WHERE chapter_slug = 'telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas';
UPDATE theory_content SET concepts_json = concepts_json || '-|---|---|---|\n| Mada I | Domalapally (1367 A.D.) | Kulyakshetram (wet land under canal, _niru nela_); Kedara (wet land) | Velibhumi (dry land) |\n| Rao Dharama Nayaka | Sayampet (1464 A.D.) | Kedara (wet land) | Krishna (black soil), Pandura |\n\n*   The above table indicates these chiefs followed systematic land administration — land revenue assessment was based on soil types. Not only were soils divided, but land under cultivation was divided into various measurements.\n\n**Land Measurements**\n\n| King | Inscription | Measurements |\n|---|---|---|\n| Mada I | Domalapally (1367 A.D.) | _Nivart_ (a land measure equal to modern acre); _Maruthuu_ (a certain/uncertain land measure generally used as equivalent to modern acre) |\n| Venna | Kandikonda (1375 A.D.) | _Tumu_ (a measure of land) |\n\n*   The breakup of cultivable lands into various sizes, and their donation to temples or individuals, reflects that **private property in land** was becoming apparent in medieval times.\n*   The ownership of the soil is a debatable question for medieval times: one school of thought believed land belonged to the entire village, shared among them equally; another group believed land belonged to the king. However, neither notion is completely correct — land grants by kings, chiefs, guilds, or commoners reveal that private proprietary rights over land existed during medieval times.\n*   Thus, increasing trade and commerce indicated economic revival and resulted in the expansion of cultivation. The founding of new villages and construction/reconstruction of tanks brought forth legal issues regarding land ownership — **private property in land became apparent** during this period under the regional powers.", "free": false}, {"partNumber": 9, "conceptId": "telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas-p9", "partName": "Sanskrit and Telugu Literature", "bodyMd": "### Sanskrit Literature\n\n**Sarvajna Singama II**, son of Anapota I, was an eminent poet who composed _Rasarnava Sudhakaram_, _Ratna Panchalika_, and _Sangeeta Sudhakaram_. His son **Rao Madha Naya** also wrote a Sanskrit book, _Raghaviyam_, a commentary on the Sanskrit Ramayana.\n\n*   **Naganatha**, a well-known Sanskrit poet of Anapota I, wrote _Madanavilasa bhanamu_.\n*   **Visveshwara Kavi** and **Appayaruyudu** flourished during the reign of **Singhamabhupala II**. **Visveshwara**, the court poet of Singamabhupala, wrote a book on _Alankara Sastra_ titled _Chamatkara Chandrika_, in which he described Sarvagna II as _sahitya silpavadhi_ (i.e., \"sculptor in literature\").\n*   **Sakalya Mallubattu**, another eminent Sanskrit scholar, composed _Nirdhyoshta Ramayanam_, _Udara Raghavamu_, and _Avyaya Sangraha nighantuvu_. He is also called **Chaturbhasha Kavita Pitamahanka** (\"poet-grandfather in four languages\"). He was court poet of **Singama Nayaka III**. His grandson **Sakalya Ayyalarya** was the laureate writer of the court of **Vedagiri I**, of the _Bhaskara Ramayanam_.\n\n### Telugu Literature\n\n**Pusapati Naganathudu** worked on _Vishnupuranam_, describing the victories of Velama kings.\n\n*   **Gaurana** wrote _Navanatha Charitra_ and _Harichandropakhyanam_ in Telugu.\n*   **Koravi Goparaju** wrote _Simhasana Dvatrimsika_ during the Velama kingdom period.\n*   **Bammara Pothana** is one of the great poets; his finest writings include _Bhogini Dandakam_, _Andhramaha Bharatham_, and _Veerabhadra Vijayam_.\n*   The Velamas of Rachakonda and Devarakonda, like other medieval rulers, tried to legitimize their power through entitlement, foliation (descent claims), and patronage to arts and letters.", "free": false}, {"partNumber": 10, "conceptId": "telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas-p10", "partName": "Art and Architecture", "bodyMd": "\n\n### Painting\n\n**Machaldevi**, the courtesan of the last Kakatiya ruler Prataparudra, is said to have maintained _Chitrasalas_ (painting museums) in Orugallu, described in _Kridabhiramam_. It appears the painting tradition continued into the Rachakonda and Devarakonda Velamas age.\n\n*   Poet **Potana**, in his greatest work _Maha Bhagavatam_, vividly described the process of mixing five important colors used for paintings.\n*   Historical paintings surviving to date are meagre in Telangana as in other regions, but the archaeological survey of the region revealed paintings of the **Padmanayaka period** at:\n    1.  **Rachakonda**, Nalgonda District\n    2.  **Devarakonda**, Nalgonda District\n    3.  **Pandavulagutta**, Warangal District\n\n**Ramanavami Paintings in Rachakonda:**\n\n*   Recently discovered paintings in a temple in Rachakonda closely match descriptions of Potana''s work; the concept appears drawn from the contemporary work _Ranganatha Ramayanam_.\n*   Found in the temple located inside the south-east entrance of the fort — the walls and roofs were once full of paintings, but Bahamani Sultans who defeated the Rachakonda Velama kings had almost all of them chiseled out, as decorations were treated against Shariat law.\n*   Only one stone slab over the roof displays a painting depicting episodes of _Putrakameshthi_ and _Asvamedha Yagas_ conducted by **Dasaratha**, as described in _Ranganath Ramayana_ (Balakanda):\n    *   One painting shows Dasaratha conducting _Putrakameshthi Yajnam_ on a platform over the bank of river Sarayu, under the guidance of Sage Vasishta and Santa-Rishyashrunga, with his three wives Kausalya, Sumitra, and Kaikeyi (the last with a wicked face).\n    *   Another displays the _Asvamedha Yagam_, showing noblemen receiving the horse that returned victorious after roaming the surrounding countries of Ayodhya, with people of the four Varnas, divine persons, sages, divine ladies, and female servants attending the sacrificial ceremonies — depicted with black outlines on white paste over the roof.\n*   The paintings are dated to roughly 650 years ago, based on an inscription of **1365 A.D.** by Rachakonda ruler **Anapota Nayaka**, found in front of the temple of Rama at Rachakonda.\n\n**Pre-Historic Paintings Continuing in Rachakonda:**\n\n*   There are pre-historic-style paintings under a rock shelter adjacent to a temple constructed by the Padanayakas. The huge cave shelter was inhabited by devotees during the period under review, attested by a medieval engraving of Lord Ganesh on the wall opposite the paintings.\n*   The propounding feature: a series of lines about a foot in length and 3 cm in width, in a row of 7 metres, depicted in ochre red colour. Adjacent to the lines is a diametric design (hoped to represent a deity), a metre in length and half a metre in width. A group of devotees follows the design, dancing, headed by a priest.\n*   The whole group painting appears to represent a deity invoked by devotees in the **Megalithic age**, some **3,000 years ago**, since several megalithic burials are noticed a short distance from the cave.\n\n**Hanuman Paintings:**\n\n*   The Padmanayakas held a unique title, _**Astadika raya**_ — indicating the eight cardinal points of the kingdom were conquered by the Padmanayakas.\n*   One can attest the eight cardinal points of the forts of the Padmanayakas bounded by three sculptures on boulders — usually near the entrance gates of the forts — including **Hanuman, Ganesh, and Bhairava**.\n*   The Hanuman sculpture is the most popular; one cannot find a village in Telangana without a Hanuman temple or sculpture — because **Vaishnavism was patronized by the Padmanayakas**, and the Vaishnavite god Hanuman was promoted throughout the kingdom.\n*   This tradition is found in:\n    1.  **Devarakonda** — the top table land of the Devarakonda fort has a huge lake surrounded by huge boulders; one has a brushed surface displaying a painting of Lord Hanuman in regular idol size of 3 feet, in red ochre with black lines where necessary, bordered (6 inches) all around.\n    2.  **Pandavulagutta** — considered the most varied site of pre-historic and historic cave paintings in Telangana. The cave complex has several natural compartments; the ending point in the complex is called **Gonthemma Kollu** — a cave with pre-historic and historic paintings under its roof. The roof-front was painted during the regnal years of the Recharla Padmanayakas. The predominant picture is Lord Hanuman, painted in red ochre in a jumping posture with a huge rod/weapon in his right hand. The name of the cave — Gonthemma — is the corrupt form of **Kunti**, mother of the Pandavas of Vaishnava faith.\n\n### Gravitational Water Supply Technology in Rachakonda\n\nThe gravitation technology used in pumping water from the **Secret Lake (Durgam Cheruvu)** to Golconda fort during the 16th century made Golconda one of the earliest kingdoms in the world to use such technology before electricity and motors were invented.\n\n*   As per an inscription found engraved on a boulder beside a lake in Rachakonda, the two lakes — **Anapota Samudram** and **Raya Samudram** — were constructed by king **Anapota Nayaka in 1368 A.D.**; a corbelled canal extends up to the palaces, in-laid in the outer walls of the palaces.\n*   By observing the structures, one can understand that drinking water was drawn from lakes at higher altitudes to palaces at lower altitudes, using **gravitational technology** to facilitate free flow of water from high to low. Royal family and nobility living in the harem/palaces obtained water in individual rooms and toilets through taps attached to the corbelled canal running through the palace walls.\n*   The **corbelled drainage system** had already existed in India from the **Indus Valley Civilization** (c. 2700 BC) onwards, but was confined to draining used water only, not drinking water.\n*   The technology of **gravitational suction of drinking water** was first used by **Raja Bhoja** inside the tank bund of Bhopal Lake and on a stream in Bhojpur, Madhya Pradesh, during the **11th century**, utilizing architectural features from Bhoja''s work _Samaraanagana Sutradhaara_.\n*   Telangana''s Kakatiyas of Warangal and Velamas of Rachakonda had already utilized these architectural features — for instance, _Jhaaraavali_, the outer roofs of temples designed to look like dropping water drops, was employed by these Telangana rulers. \n\n*   Similarly, the Velama kings of Rachakonda may have followed the gravitation technology coined by Bhoja, which found its further way to Golconda two centuries later.\n\n### Sculpture and Architecture\n\nBy and large, the architecture and sculpture of Telangana after the Vishnukundis is characterized by **Chalukyan style**, continued and improved by the Kakatiya dynasty, and the same tradition was continued by the Velamas of Rachakonda and Devarakonda.\n    \n*   Though the quality, quantity, and diversity of Padmanayaka sculpture/architecture was inferior to their rich predecessors the Kakatiyas, the Padmanayakas had some significant architectural features to their credit:\n    \n    1.  Construction of **temples on top of hills**\n    2.  Construction of **temples for Lord Narasimha in caves** on top of hills\n    3.  **Sculptures of Bhairava, Hanuman, and Ganesha** on the natural borders near the fortifications of temples at eight cardinal points\n*   Almost all these features are found in the forts/temples at the following places: Rachakonda, Devarakonda, Koulasa, Bheemgal, Hastalapur, Ramagiri Khilla, Koilkonda, Thirumalanatha Konda, Pedda Revalla, Bhuvanagiri, Charigonda, Urlugonda, Anantagiri, Umamaheshvaram, Jatararevu, Mannanur, Domalapalli, Mattapalli, Vellatur, Kandikonda, Inugurti, and Badigetpalli. \n    \n\n### Rachakonda — Architectural Beauty\n\nAmongst all places developed by the Velamas of Rachakonda, Rachakonda itself stands first in architectural beauty, with:\n    1.  **Religious architecture**: Temples — lost sculptures\n    2.  **Secular architecture**: Fortifications, tanks, canals, wells\n*   Rachakonda and Devarakonda Velamas initially patronized **Saivism** and subsequently embraced the faith of **Vaishnavism**. Therefore, two types of temples are found at their capital Rachakonda:\n    *   **Saivite temples** — constructed on land surface\n    *   **Vaishnavite temples** — placed on high platforms or in caves\n*   Numerous temples are found in Rachakonda fort, especially in its south-west stretch.\n\n**The Ramalayam (Temple of Lord Rama):**\n\n*   The most important and earliest temple in Rachakonda fort, located in the south-western portion. It was built by the first independent ruler of the Padmanayaka dynasty, **Anapota Nayaka**, in **1365 A.D.** (per the site inscription).\n*   The temple was constructed over a natural cave formed under a boulder — since the roof of the cave is still invoked today, it can be said the cave was earlier a cave temple of pre-historic people.\n*   Local tradition holds the present idols of Lord Rama, Mother Seetha, Laxmana, and Hanuman were brought here from over the fort, since royal harem members could not climb the fort for _darshan_ and _puja_.\n*   The temple is architecturally simple, with a **Rangamantapa, Dhvajastambham,** and **Prahari wall**.\n*   A pair of foot prints were engraved on the hillock north of the Ramalayam, but a single-hall temple nearby, by its architectural style, reveals it was built for **Jains** during the reign of the **Rashtrakutas** or their successors the **Western Chalukyas of Kalyani**, when Jainism was in vogue in Telangana.\n\n**Naganayakonda Vaishnavite Temple:**\n\n*   From the small temple, three routes lead eastward: two into the **Naganayani Fort**, and one into the valley between the Naganayani Fort and the Kacheri Fort.\n*   The northernmost route leads to the **Naganayakonda Fort**, home to a masterpiece Vaishnavite temple.\n*   The temple was deserted and its sacred idols stolen long ago, so it cannot now be said with certainty which deity it was constructed for.\n*   However, it can be confirmed as a **Vaishnavite temple**, since the _Dvarapala_ sculptures are of Lord Hanuman on one side and Lord Garuda on the other — a unique architectural feature that came into being during the Padmanayaka period. Similar sculptures are found in front of two types of temples built by the Padmanayakas: temples of Lord Rama, and temples of Lord Laxmi Narasimha.\n*   Since almost all Narasimha temples were built in caves/rock caverns, the temple under review may safely be ascribed to Lord Rama, as it was constructed on land surface, though on hilly space.\n*   The temple complex has **five structures**: the main temple, **Kalyana Mandapam**, **Prakaara** (enclosing wall), cloisters, and an open well-like pond of large parameters.\n*   The main temple has a sanctum sanctorum (_garbhagriha_), _ardhagriha_ or _shukanashi_, and _Mukha Mandapam_ or _Navaranga Mandapam_. The _ardha mandapa_ has sculptures of Garuda and Hanuman on either side of its door jambs. The _Garbhagriha_ is pinnacled by a _Sikhara_ in pyramidal steps.' WHERE chapter_slug = 'telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas';
UPDATE theory_content SET concepts_json = concepts_json || '\n*   With these features, the temple appears built in the **Chalukyan style of architecture**. Though Chalukyan style is represented, it seems to have been constructed by the Recharla Padmanayakas only, for two reasons:\n    1.  The door jambs of the _ardhamandapa_ carry sculptures of Garuda and Hanuma, deities invoked by the Padmanayakas.\n    2.  There is no material evidence or inscription tracing it to the Chalukyan period in or around Rachakonda or elsewhere.\n*   **Kalyana Mandapa** stands to the left (north) of the main temple. A long rock basement lies in front of the temple — it seems to represent a long cloister of cells for devotees to rest/stay during festivals. A long well-like pond is constructed at a distance of 200 metres from the temple.", "free": false}, {"partNumber": 11, "conceptId": "telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas-p11", "partName": "Summary", "bodyMd": "The Velamas of Rachakonda and Devarakonda ruled over this region for about **152 years**, holding sway over the area lying between the rivers **Godavari and Krishna**.\n\n*   The reign of the Velamas of Rachakonda and Devarakonda is considered a **glorious epoch** in Telangana history, witnessing remarkable progress in art and architecture, language and literature, religion, and philosophy.\n*   After the Kakatiyas, the Recherla Velamas left their impress as native rulers of Telangana for more than a century. When Warangal fort was lost to the Bahmanis, the Velamas shifted to surrounding areas, and remained **Jagirdars, Maqtedars,** and **Deshmukhs** until recent times under **Nizam rule**.\n*   The regional power of the Recharla Padmanayakas of Rachakonda and Devarakonda — so far often considered a \"forgotten period\" or \"dark phase\" in the annals of medieval Andhra history — is, in fact, a **brilliant epoch**, witnessing significant transitions in the socio-economic, political, and cultural spheres of the state.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter8-rachakonda-rulers-and-musunuri-nayakas';
